package com.arc_e_tect.example.generated;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Value object whose getters, setters, {@code equals}, {@code hashCode},
 * {@code toString}, and constructors are generated by Lombok's {@link Data},
 * {@link NoArgsConstructor}, and {@link AllArgsConstructor} annotations.
 *
 * <p>None of that generated code ever appears in this source file — Lombok
 * synthesises it directly into {@code Customer.class} at compile time, and
 * stamps every synthesised member with {@code @lombok.Generated}. JaCoCo
 * already excludes those members from coverage without any configuration;
 * {@code jacocoExclusionReport { includeGeneratedAnnotationExclusions = true }}
 * makes that exclusion visible in the audit report.</p>
 *
 * <p>{@link #displayName()} is hand-written and carries no such annotation, so
 * it shows up as ordinary, coverable code — not in the generated-exclusion
 * report.</p>
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Customer {

    private String customerId;
    private String fullName;

    public String displayName() {
        return fullName + " (" + customerId + ")";
    }
}
